entries[79848] = { ["name"] = "Glühende Rüstung", ["text"] = "100 Meter Reichweite\nSofort\nVerursacht Feuerschaden." }
entries[79849] = { ["name"] = "Glühende Rüstung", ["text"] = "Sofort\nVerursacht Feuerschaden, wenn getroffen, erhöht Eure kritische Zaubertrefferchance um 3% und verringert die Chance, kritische Treffer zu erleiden, um 5%. Es kann immer nur eine Art Rüstungszauber gleichzeitig aktiv sein. Hält 10 Min. lang an.\n(3s Abklingzeit)" }
entries[79850] = { ["name"] = "Frostnova", ["text"] = "30 Mana\nWirken in 2 sek.\nVerursacht Frostschaden bei in der Nähe befindlichen Feinden und macht sie bis zu 4 Sek. lang bewegungsunfähig." }
entries[79851] = { ["name"] = "Dolchfächer", ["text"] = "40 Energie\nSofort\nBenötigt Nahkampfwaffe\nWirft sofort Dolche nach allen nahen Feinden und verursacht 100% Waffenschaden." }
entries[79852] = { ["name"] = "Ausweiden", ["text"] = "60 Energie Nahkampfreichweite\nSofort\nBenötigt Nahkampfwaffe\nFinishing-Move, der Schaden verursacht." }
entries[79853] = { ["name"] = "Entrinnen", ["text"] = "Sofort\nErhöht die Ausweichchance des Zaubernden um 35%." }
entries[79854] = { ["name"] = "Feuerball", ["text"] = "15 Mana 40 Meter Reichweite\nWirken in 3 sek.\nFügt einem Gegner Feuerschaden zu." }
entries[79855] = { ["name"] = "Feuerschlag", ["text"] = "25 Mana 20 Meter Reichweite\nSofort\nFügt einem Gegner Feuerschaden zu." }
entries[79856] = { ["name"] = "Flammenstoß", ["text"] = "35 Mana 30 Meter Reichweite\nWirken in 3 sek.\nLässt eine Flammensäule niedergehen, die alle Feinde in einem ausgewählten Gebiet verbrennt und ihnen 8 Sek. lang alle 2 Sek. zusätzlichen Schaden zufügt." }
entries[79857] = { ["name"] = "Druckwelle", ["text"] = "35 Mana\nWirken in 3 sek.\nEntfesselt eine Flammenwelle, die nahen Feinden Feuerschaden zufügt und ihr Bewegungstempo 6 Sek. lang verringert." }
entries[79858] = { ["name"] = "Frostblitz", ["text"] = "15 Mana 40 Meter Reichweite\nWirken in 3 sek.\nFügt einem Feind Frostschaden zu und verringert 4 Sek. lang sein Bewegungstempo." }
entries[79859] = { ["name"] = "Eislanze", ["text"] = "20 Mana 35 Meter Reichweite\nSofort\nFügt einem feindlichen Ziel Frostschaden zu. Eingefrorene Ziele erleiden den doppelten Schaden." }
entries[79860] = { ["name"] = "Blizzard", ["text"] = "35 Mana 30 Meter Reichweite\nWirken in 2 sek.\nRuft einen Blizzard herbei, der 8 Sek. lang anhält und Feinden im ausgewählten Gebiet alle 2 Sek. Frostschaden zufügt." }
entries[79861] = { ["name"] = "See Raptor: Forcecast Teleport Out" }
entries[79862] = { ["name"] = "Meucheln", ["text"] = "60 Energie Nahkampfreichweite\nSofort\nFügt einem Gegner 150% Schaden zu, aber nur, wenn von hinten angegriffen wird." }
entries[79863] = { ["name"] = "Blutsturz", ["text"] = "40 Energie Nahkampfreichweite\nSofort\nVerursacht Waffenschaden und erhöht den erlittenen körperlichen Schaden eines Gegners 10 Sek. lang um 20%." }
entries[79864] = { ["name"] = "Schattenschritt", ["text"] = "20 Energie 40 Meter Reichweite\nSofort 30 sek. Abklingzeit\nVersucht, in die Schatten zu tauchen, um hinter dem Gegner zu erscheinen." }
entries[79865] = { ["name"] = "Frostrüstung", ["text"] = "Sofort 10 sek. Abklingzeit\nUmgibt den Zaubernden mit einer Frostschicht, die 30 Min. lang bestehen bleibt. Das dicke Eis erhöht die Rüstung, verlangsamt das Bewegungstempo von Nahkampfangreifern und erhöht die Zeit zwischen ihren Angriffen." }
entries[79866] = { ["name"] = "Tödlicher Wurf", ["text"] = "20 Energie 30 Meter Reichweite\nSofort\nWirft einen Dolch auf ein gegnerisches Ziel und verursacht 24 to 29% Waffenschaden. Unterbricht außerdem das Wirken von Zaubern und verhindert 3 Sek. lang, dass diese Art Zauber gewirkt werden kann." }
entries[79867] = { ["name"] = "Phase 20 to Normal" }
entries[79868] = { ["name"] = "Arkanschlag", ["text"] = "7% von Grundmana 30 Meter Reichweite\nWirken in 2.5 sek.\nÜberzieht einen Feind mit Energie und verursacht Arkanschaden. Mit jedem Wirken von 'Arkanschlag' werden der verursachte Schaden aller Arkanzauber um 10% und die Manakosten von 'Arkanschlag' um 150% erhöht. Dieser Effekt ist bis zu 4-mal stapelbar und hält 6 Sek. lang an oder bis ein Arkanzauber außer 'Arkanschlag' gewirkt wurde." }
entries[79869] = { ["name"] = "Arkane Geschosse", ["text"] = "35 Mana 30 Meter Reichweite\nKanalisiert (Wirken in 5 sek.)\nSchleudert magische Geschosse auf einen Feind und verursacht 5 Sek. lang pro Sekunde Arkanschaden." }
entries[79870] = { ["name"] = "Wilde Attacke", ["text"] = "5 Wut 8 - 25 Meter Reichweite\nSpontanzauber 15 sek. Abklingzeit\nStürmt auf einen Gegner zu, macht ihn unbeweglich und unterbricht gewirkte Zauber. Hält bis Abbruch lang an." }
entries[79871] = { ["name"] = "Tollkühnheit", ["text"] = "Sofort\nImmun gegen Furchteffekte.\nAlle Angriffe treffen kritisch.\nRüstung um 35% verringert." }
entries[79872] = { ["name"] = "Schockwelle", ["text"] = "Wirken in 2 sek. 20 sek. Abklingzeit\nSchickt dem Krieger eine Energiewelle voraus, verursacht Schaden und betäubt 4 Sek. lang alle Einheiten innerhalb eines kegelförmigen Bereichs von 10 Metern." }
entries[79875] = { ["name"] = "Ongolongoschmettern!", ["text"] = "10 Meter Reichweite\nWirken in 0.5 sek.\nStößt das Ziel zurück." }
entries[79876] = { ["name"] = "Blutdurst", ["text"] = "Nahkampfreichweite\nSofort\nHeilt den Zaubernden um 1% seiner maximalen Gesundheit." }
entries[79877] = { ["name"] = "Blutdurst", ["text"] = "Nahkampfreichweite\nSofort\nGreift das Ziel sofort an und verursacht 120% normalen Waffenschaden. Zudem stellen erfolgreiche Nahkampfangriffe 1% der maximalen Gesundheit wieder her. Der Effekt hält 10 Sek. lang an." }
entries[79878] = { ["name"] = "Blutdurst", ["text"] = "Nahkampfreichweite\nSofort 10 sek. Abklingzeit\nBenötigt Nahkampfwaffe\nGreift das Ziel sofort an und verursacht 120% normalen Waffenschaden. Zudem stellen erfolgreiche Nahkampfangriffe 1% der maximalen Gesundheit wieder her. Der Effekt hält 10 Sek. lang an." }
entries[79879] = { ["name"] = "Elektrische Entladung", ["text"] = "Unbegrenzte Reichweite\nSofort\nFügt bis zu 3 Gegnern im Umkreis von 8 Metern 43875 to 46125 Naturschaden zu." }
entries[79880] = { ["name"] = "Verlangsamen", ["text"] = "25 Mana 30 Meter Reichweite\nSofort\nErhöht die Zeit zwischen den Angriffen eines Gegners um 25%, verlangsamt sein Zaubertempo um 25% und sein Bewegungstempo um 25%. Hält 6 Sek. lang an." }
entries[79881] = { ["name"] = "Zerschmettern", ["text"] = "Nahkampfreichweite\nWirken in 1.5 sek.\nZerschmettert den Gegner und verursacht Waffenschaden plus zusätzlichen Schaden." }
entries[79882] = { ["name"] = "Niederstoßen" }
entries[79883] = { ["name"] = "Zerschmetternder Wurf", ["text"] = "30 Meter ReichweiteWirken in 1.5 sek. 5 min Abklingzeit\nBenötigt Nahkampfwaffe\nWirft Eure Waffe nach dem Feind. Verursacht Waffenschaden verringert die Rüstung des Ziels 10 Sek. lang um 20%." }
entries[79884] = { ["name"] = "Blitzschlag", ["text"] = "15 Mana 40 Meter Reichweite\nWirken in 3 sek.\nDeckt einen Feind mit Blitzschlägen ein und fügt ihm Naturschaden zu." }
entries[79885] = { ["name"] = "Herzstoß", ["text"] = "1 Blutrune / -10 Runenmacht Nahkampfreichweite\nSpontanzauber\nBenötigt Nahkampfwaffe\nSchlägt das Ziel und seinen nächsten Verbündeten sofort. Fügt dem Primärziel 110% Waffenschaden und dem Sekundärziel 55% Waffenschaden zu." }
entries[79886] = { ["name"] = "Lavaeruption", ["text"] = "10% von Grundmana 30 Meter Reichweite\nWirken in 3.5 sek.\nIhr schleudert flüssige Lava auf das Ziel, die Feuerschaden verursacht." }
entries[79887] = { ["name"] = "Tod und Verfall", ["text"] = "30 Meter Reichweite\nSofort\nFügt allen Zielen im betroffenen Gebiet 10 Sek. lang alle 1 Sek. Schattenschaden zu." }
entries[79888] = { ["name"] = "Blitzableiter", ["text"] = "45 Meter Reichweite\nSofort\nInfiziert einen Feind 15 Sek. lang, wodurch an allen in der Nähe befindlichen Verbündeten alle 2 Sek. Naturschaden verursacht wird." }
entries[79889] = { ["name"] = "Blitzableiter", ["text"] = "Sofort\nFügt nahen befreundeten Einheiten Naturschaden zu." }
entries[79890] = { ["name"] = "Flammenschock", ["text"] = "25 Mana 20 Meter Reichweite\nSofort\nVerbrennt sofort einen Feind und fügt ihm dann 12 Sek. lang alle 3 Sek. zusätzlichen Feuerschaden zu." }
entries[79891] = { ["name"] = "Horn des Winters", ["text"] = "-10 Runenmacht\nSpontanzauber\nDer Todesritter bläst das Horn des Winters und erhält 10 Runenmacht. Stärke und Beweglichkeit werden um 5 erhöht. Hält 2 Min. lang an." }
entries[79892] = { ["name"] = "Wasserschild", ["text"] = "Sofort\nDer Zaubernde wird von 3 Wasserkugeln umgeben. Gegen den Zaubernden gerichtete Angriffe oder Zauber verursachen Frostschaden und verlangsamen das Zaubertempo des Angreifers. 3 Aufladungen. Hält 10 Min. lang an.\n(4s Abklingzeit)" }
entries[79893] = { ["name"] = "Blutwurm", ["text"] = "30 Meter Reichweite\nSofort\nErschafft einen Blutwurm, der nahe Ziele angreift. Hält 8 Sek. lang an." }
entries[79894] = { ["name"] = "Todesgriff", ["text"] = "30 Meter Reichweite\nSofort\nNutzt die Mächte unheiliger Energien, die alle Materie umgibt und bindet, um das Ziel zum Todesritter hinzuziehen und es zu zwingen, ihn 3 Sek. lang anzugreifen." }
entries[79895] = { ["name"] = "Froststoß", ["text"] = "-10 Runenmacht Nahkampfreichweite\nSpontanzauber\nBenötigt Nahkampfwaffe\nSchlägt das Ziel sofort und verursacht 110% Waffenschaden als Frostschaden." }
